/bin/zsh -lc "python3 - <<'PY'
import json
from pathlib import Path
expected = {
    'project': 'catalog-api',
    'cache': {
        'ttl_seconds': 600,
        'max_entries': 500,
        'eviction_policy': 'fifo',
        'namespace': 'catalog-shared',
        'cache_misses': True,
    },
}
def unique_object(pairs):
    result = {}
    for key, value in pairs:
        assert key not in result, f'Duplicate key: {key}'
        result[key] = value
    return result
actual = json.loads(Path('config.json').read_text(), object_pairs_hook=unique_object)
def validate(actual, expected, path='"'$'"'):
    assert type(actual) is type(expected), f'Type mismatch at {path}'
    if isinstance(expected, dict):
        assert actual.keys() == expected.keys(), f'Field mismatch at {path}'
        for key in expected:
            validate(actual[key], expected[key], f'{path}.{key}')
    else:
        assert actual == expected, f'Value mismatch at {path}'
validate(actual, expected)
print('Validated complete JSON: all v1 fields, values, and types match the recalled historical contract.')
PY"
